/* Token Launch Radar — one palette, one spacing scale, one type scale. Dark by choice: the board is
   read at night, next to a chart. Everything below is spacing, a hairline and a type step; there is
   no framework here. */

:root {
  --canvas: #070d0c;
  --surface: #0c1413;
  --surface-2: #101b19;
  --hairline: #1b2b28;
  --hairline-soft: #14211f;
  --ink: #e8f3ef;
  --ink-dim: #9db4ad;
  --muted: #6f8a83;
  --mint: #5df2b4;
  --mint-soft: rgba(93, 242, 180, 0.12);
  --amber: #f7c860;
  --rose: #ff8fa8;
  --radius: 10px;
  --radius-lg: 16px;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
  --s8: 72px;
  --body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --num: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--body);
  -webkit-font-smoothing: antialiased;
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.025em; text-wrap: balance; }
h1 { font-size: 36px; line-height: 1.08; font-weight: 600; }
h2 { font-size: 22px; line-height: 1.2; font-weight: 600; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 600; letter-spacing: 0.01em; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.wrap { width: min(1280px, calc(100% - 64px)); margin-inline: auto; }
.dim { color: var(--muted); }

.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s3);
  background: var(--mint); color: #04120d; border-radius: var(--radius);
}
.skip:focus { left: var(--s4); top: var(--s4); z-index: 9; }

/* ---------- header ---------- */
.top {
  border-bottom: 1px solid var(--hairline);
  background: linear-gradient(180deg, #0a1211 0%, #070d0c 100%);
}
.top-in {
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--s4); min-height: 60px;
}
.brand { display: flex; align-items: center; gap: var(--s3); }
.mark {
  width: 12px; height: 12px; border-radius: 3px;
  background: var(--mint);
  box-shadow: 0 0 0 4px var(--mint-soft), 0 0 18px rgba(93, 242, 180, 0.55);
}
.brand-text {
  font: 600 13px/1 var(--num);
  letter-spacing: 0.22em;
}
.chip {
  font: 500 11px/1 var(--num);
  padding: 5px 8px; border-radius: 999px;
  border: 1px solid var(--hairline); color: var(--ink-dim);
  letter-spacing: 0.06em;
}
.snapshot { font: 400 12px/1.4 var(--num); color: var(--muted); text-align: right; }
.snapshot b { color: var(--ink-dim); font-weight: 500; }

/* ---------- hero ---------- */
.hero { padding: var(--s6) 0 var(--s5); border-bottom: 1px solid var(--hairline-soft); }
h1 .dim { color: #4d6a63; }
.lede {
  margin-top: var(--s3); max-width: 74ch;
  color: var(--ink-dim); font-size: 16px;
}
.stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--s3); margin: var(--s4) 0 0;
}
.stat {
  padding: var(--s3) var(--s4); border: 1px solid var(--hairline); border-radius: var(--radius-lg);
  background: var(--surface);
}
.stat dt { font-size: 12px; color: var(--muted); letter-spacing: 0.04em; text-transform: uppercase; }
.stat dd {
  margin: 6px 0 0; font: 500 24px/1 var(--num);
  font-variant-numeric: tabular-nums; letter-spacing: -0.02em;
}
.stat dd small { font-size: 13px; color: var(--muted); margin-left: 6px; letter-spacing: 0; }

/* ---------- tabs ---------- */
.tabs { display: flex; gap: var(--s2); padding: var(--s4) 0 0; }
.tab {
  background: none; border: 1px solid transparent; border-bottom: none;
  padding: 10px 14px; border-radius: var(--radius) var(--radius) 0 0;
  color: var(--muted); font-size: 14px; font-weight: 500;
}
.tab:hover { color: var(--ink-dim); background: var(--surface); }
.tab[aria-selected="true"] {
  color: var(--ink); background: var(--surface);
  border-color: var(--hairline); position: relative; top: 1px;
}

/* ---------- controls ---------- */
.controls {
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--s3);
  padding: var(--s4) 0; border-bottom: 1px solid var(--hairline);
}
.field { display: flex; flex-direction: column; gap: 6px; }
.field > span {
  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted);
}
.field.grow { flex: 1 1 240px; }
.field input[type="search"], .field select {
  height: 38px; padding: 0 var(--s3);
  background: var(--surface); border: 1px solid var(--hairline);
  border-radius: var(--radius); color: var(--ink); min-width: 150px;
}
.field input[type="search"]:focus, .field select:focus {
  outline: 2px solid var(--mint-soft); border-color: #2c4a43;
}
.field.check {
  flex-direction: row; align-items: center; gap: var(--s2);
  height: 38px; padding: 0 var(--s3);
  border: 1px solid var(--hairline); border-radius: var(--radius); background: var(--surface);
}
.field.check span { font-size: 13px; letter-spacing: 0; text-transform: none; color: var(--ink-dim); }
.field.check input { accent-color: var(--mint); }
.ghost {
  height: 38px; padding: 0 var(--s4); background: none;
  border: 1px solid var(--hairline); border-radius: var(--radius); color: var(--ink-dim);
}
.ghost:hover { border-color: #2c4a43; color: var(--ink); }

/* ---------- table ---------- */
.table-head, .row {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 110px 74px 108px 88px 240px;
  gap: var(--s3); align-items: center;
}
.table-head {
  padding: var(--s3) var(--s2); border-bottom: 1px solid var(--hairline);
  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted);
}
.table-head .c-num { text-align: right; }
.table-head .wide { text-align: right; }
.rows { list-style: none; margin: 0; padding: 0; }
.row {
  width: 100%; text-align: left; background: none; border: none;
  border-bottom: 1px solid var(--hairline-soft);
  padding: 8px var(--s2); color: inherit;
}
.row:hover, .row:focus-visible { background: var(--surface); outline: none; }
.row.is-open { background: var(--surface-2); }
.c-rank { font: 400 12px/1 var(--num); color: var(--muted); }
.c-name { min-width: 0; }
.p-name { font-weight: 550; font-size: 14.5px; letter-spacing: -0.01em; }
.p-meta {
  margin-top: 3px; font: 400 11.5px/1.3 var(--num); color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.flag {
  display: inline-block; margin-left: 6px; padding: 2px 6px; border-radius: 999px;
  font: 500 10px/1 var(--num); letter-spacing: 0.05em;
  border: 1px solid #2b4a41; color: var(--mint); background: var(--mint-soft);
}
.flag.early { border-color: #4a3f22; color: var(--amber); background: rgba(247, 200, 96, 0.1); }
.c-num { text-align: right; font: 400 13px/1.2 var(--num); font-variant-numeric: tabular-nums; }
.c-num.neg { color: var(--rose); }
.c-num.pos { color: var(--mint); }
.c-num.faint { color: var(--muted); }
.value { text-align: right; }
.value b { font: 500 14.5px/1.2 var(--num); font-variant-numeric: tabular-nums; }
.bar {
  display: block; height: 3px; margin-top: 5px; border-radius: 2px;
  background: var(--hairline);
}
.bar > i { display: block; height: 100%; border-radius: 2px; background: linear-gradient(90deg, #2a8f6c, var(--mint)); }
.band { font: 400 10.5px/1 var(--num); color: var(--muted); margin-top: 4px; }
.empty, .count { padding: var(--s5) var(--s2); color: var(--muted); font-size: 13px; }

/* ---------- live view ---------- */
.section-lede { margin: var(--s3) 0 var(--s5); color: var(--ink-dim); max-width: 80ch; }
.live-head, .row.live {
  grid-template-columns: minmax(0, 1fr) 120px 130px 80px 200px;
}
/* ---------- method ---------- */
.method { padding-bottom: var(--s7); }
.method h3 { margin: var(--s6) 0 var(--s3); }
.formula {
  margin-top: var(--s5); border: 1px solid var(--hairline); border-radius: var(--radius-lg);
  background: var(--surface); overflow: hidden;
}
.formula-line {
  display: grid; grid-template-columns: 110px 24px minmax(0, 1fr);
  gap: var(--s2); padding: 13px var(--s4);
  border-bottom: 1px solid var(--hairline-soft); align-items: baseline;
}
.formula-line:last-child { border-bottom: none; }
.formula-line .k { font: 500 12px/1 var(--num); color: var(--mint); letter-spacing: 0.04em; }
.formula-line .eq { color: var(--muted); font-family: var(--num); }
.formula-line .v { color: var(--ink-dim); font-size: 13.5px; }
.formula-line b { color: var(--ink); font-family: var(--num); font-weight: 500; }
.formula-line.strong { background: var(--surface-2); }
.formula-line.strong .v { color: var(--ink); }
.note { margin-top: var(--s4); color: var(--muted); font-size: 13px; max-width: 88ch; }
.cat-head, .row.cat { grid-template-columns: minmax(0, 1fr) 130px 130px 130px 130px; }
.limits { margin: var(--s3) 0 0; padding-left: 20px; color: var(--ink-dim); font-size: 13.5px; }
.limits li { margin-bottom: 6px; }

/* ---------- drawer ---------- */
.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 100%);
  background: var(--surface); border-left: 1px solid var(--hairline);
  box-shadow: -40px 0 80px rgba(0, 0, 0, 0.55);
  overflow-y: auto; z-index: 20;
}
.drawer-in { padding: var(--s6) var(--s6) var(--s8); }
.drawer-close {
  position: absolute; top: var(--s4); right: var(--s4);
  width: 32px; height: 32px; border-radius: 8px; background: var(--surface-2);
  border: 1px solid var(--hairline); color: var(--ink-dim); font-size: 16px; line-height: 1;
}
.drawer-close:hover { color: var(--ink); }
.d-eyebrow { font: 500 11px/1 var(--num); letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
.d-title { margin-top: var(--s3); font-size: 26px; }
.d-sub { margin-top: var(--s2); font: 400 12px/1.4 var(--num); color: var(--muted); }
.d-value {
  margin: var(--s5) 0 var(--s2); font: 500 40px/1 var(--num);
  letter-spacing: -0.03em; font-variant-numeric: tabular-nums;
}
.d-band { font: 400 12px/1.4 var(--num); color: var(--muted); }
.d-block { margin-top: var(--s5); }
.d-block h3 { font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
.d-grid {
  display: grid; grid-template-columns: 1fr auto; gap: 7px var(--s4);
  margin-top: var(--s3); font: 400 12.5px/1.4 var(--num);
}
.d-grid dt { color: var(--muted); }
.d-grid dd { margin: 0; text-align: right; color: var(--ink-dim); }
.d-grid dd b { color: var(--ink); font-weight: 500; }
.steps { margin: var(--s3) 0 0; padding: 0; list-style: none; counter-reset: step; }
.steps li {
  counter-increment: step; position: relative;
  padding: 0 0 var(--s4) 30px; border-left: 1px solid var(--hairline);
  margin-left: 9px; font-size: 13.5px; color: var(--ink-dim);
}
.steps li:last-child { border-left-color: transparent; padding-bottom: 0; }
.steps li::before {
  content: counter(step);
  position: absolute; left: -10px; top: -2px;
  width: 19px; height: 19px; border-radius: 999px;
  background: var(--surface-2); border: 1px solid var(--hairline);
  color: var(--mint); font: 500 10px/17px var(--num); text-align: center;
}
.steps .cost { display: block; margin-top: 5px; font: 400 11.5px/1.4 var(--num); color: var(--muted); }
.steps .cost b { color: var(--ink-dim); font-weight: 500; }

/* ---------- footer ---------- */
.foot {
  border-top: 1px solid var(--hairline); padding: var(--s5) 0;
  font-size: 12px; color: var(--muted);
}
.foot .wrap { display: flex; justify-content: space-between; gap: var(--s4); flex-wrap: wrap; }

@media (max-width: 1080px) {
  .table-head, .row { grid-template-columns: 36px minmax(0, 1fr) 90px 96px 180px; }
  .c-num.age-col, .c-num.mult-col { display: none; }
  h1 { font-size: 32px; }
}
@media (max-width: 760px) {
  .wrap { width: calc(100% - 32px); }
  .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .table-head, .row { grid-template-columns: 28px minmax(0, 1fr) 96px; }
  .c-num.tvl-col, .c-num.growth-col { display: none; }
}
